import asyncio

async def chain_promises(fns):
    result = None
    for i, fn in enumerate(fns):
        if i == 0:
            result = await fn()
        else:
            result = await fn(result)
    return result

async def parallel_promises(fns):
    return await asyncio.gather(*[fn() for fn in fns])

async def retry_promise(fn, retries=3, delay=0.1):
    for attempt in range(retries):
        try:
            return await fn()
        except Exception:
            if attempt == retries - 1:
                raise
            await asyncio.sleep(delay)

