async function chainPromises(fns) {
  let result;
  for (let i = 0; i < fns.length; i++) {
    result = i === 0 ? await fns[i]() : await fns[i](result);
  }
  return result;
}

async function parallelPromises(fns) {
  return Promise.all(fns.map(fn => fn()));
}

async function retryPromise(fn, retries = 3, delay = 100) {
  for (let i = 0; i < retries; i++) {
    try {
      return await fn();
    } catch (err) {
      if (i === retries - 1) throw err;
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}
